{
  "title": "TB Transmission Learning Game",
  "perWatchSecond": 0.5,
  "levels": [
    {
      "kind": "hook",
      "finding": 0,
      "title": "Elimination via treatment",
      "goal": "See how increasing treatment changes the infectious peak.",
      "control": {
        "parameter": "delta",
        "label": "Treatment rate",
        "lowEnd": "0.5",
        "highEnd": "1.5"
      },
      "watch": "Infectious population (i)",
      "whatIf": {
        "prompt": "What if the treatment rate is doubled to 1.34?",
        "parameter": "delta",
        "value": 1.34
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 36,
        "relation": "lower",
        "by": 30
      },
      "effect": "Doubling the treatment rate lowers the infectious peak by about 72 cases.",
      "prediction": {
        "prompt": "Predict how the infectious peak will change when treatment is doubled.",
        "claimed": "Infectious peak will be lower",
        "other": "Infectious peak will be higher"
      },
      "passage": {
        "title": "Headline result",
        "quote": "The results suggest that optimal conditions could lead to the elimination of TB."
      },
      "carryForward": "Higher treatment reduces infection."
    },
    {
      "kind": "background",
      "finding": 1,
      "title": "Impact of progression speed",
      "goal": "Observe how speeding progression from exposed to infectious changes the infectious peak.",
      "control": {
        "parameter": "gamma",
        "label": "Progression rate",
        "lowEnd": "0.3",
        "highEnd": "0.9"
      },
      "watch": "Infectious population (i)",
      "whatIf": {
        "prompt": "What if the progression rate is doubled to 0.96?",
        "parameter": "gamma",
        "value": 0.96
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 36,
        "relation": "higher",
        "by": 100
      },
      "effect": "Doubling the progression rate raises the infectious peak by about 103 cases.",
      "prediction": {
        "prompt": "Predict the effect on the infectious peak when progression is doubled.",
        "claimed": "Infectious peak will be higher",
        "other": "Infectious peak will be lower"
      },
      "passage": {
        "title": "Threshold",
        "quote": "We obtained $R_0 = 2.67$ for the estimated model parameters, which are greater than one, indicating that the tuberculosis is continuously multiplying."
      },
      "carryForward": "Faster progression increases cases."
    },
    {
      "kind": "idea",
      "finding": 2,
      "title": "Reducing treatment slows decline",
      "goal": "See what happens when treatment rate is cut in half.",
      "control": {
        "parameter": "delta",
        "label": "Treatment rate",
        "lowEnd": "0.2",
        "highEnd": "0.8"
      },
      "watch": "Infectious population (i)",
      "whatIf": {
        "prompt": "What if the treatment rate is halved to 0.335?",
        "parameter": "delta",
        "value": 0.335
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 36,
        "relation": "higher",
        "by": 70
      },
      "effect": "Halving the treatment rate raises the infectious peak by about 71 cases.",
      "prediction": {
        "prompt": "Predict the infectious peak when treatment is halved.",
        "claimed": "Infectious peak will be higher",
        "other": "Infectious peak will be lower"
      },
      "passage": {
        "title": "Treatment effect",
        "quote": "The result revealed that the infectious population decreases as the treatment rate of infected individuals increases; in the long run, this may lead to the eradication of the disease from the community."
      },
      "carryForward": "Less treatment leads to more infection."
    },
    {
      "kind": "method",
      "finding": 3,
      "title": "Recruitment drives infection",
      "goal": "Explore how increasing population recruitment changes infectious numbers.",
      "control": {
        "parameter": "lambda",
        "label": "Recruitment rate",
        "lowEnd": "10",
        "highEnd": "20"
      },
      "watch": "Infectious population (i) at time 36",
      "whatIf": {
        "prompt": "What if recruitment is doubled to 30?",
        "parameter": "lambda",
        "value": 30
      },
      "difference": {
        "compartment": "i",
        "summary": "at",
        "at": 36,
        "time": 36,
        "relation": "higher",
        "by": 30
      },
      "effect": "Doubling recruitment raises the infectious count at year 36 by about 30 individuals.",
      "prediction": {
        "prompt": "Predict the infectious count at year 36 when recruitment is doubled.",
        "claimed": "Infectious count will be higher",
        "other": "Infectious count will be lower"
      },
      "passage": {
        "title": "Sensitivity drivers",
        "quote": "contact rate ($beta$), recruitment rate ($Lambda$), the loss of protection for the vaccination rate ($theta$), and rate of progression from the exposed class to the infectious class ($gamma$) were the most important factors."
      },
      "carryForward": "More recruitment fuels spread."
    }
  ],
  "limits": [
    "Control values must stay within realistic bounds.",
    "Predictions are made before the What‑If runs."
  ]
}
